{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill proposes new security requirements for public and public charter school buildings that are constructed or remodeled. For buildings constructed or remodeled between July 1, 2023, and July 1, 2025, the law would require clear entry-resistant film on all exterior entry and basement level windows and doors.",
      "rationale": "Conveys the covered schools, construction or remodeling condition, applicable date window, and required entry-resistant film on the specified windows and doors."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "For buildings constructed or remodeled on or after July 1, 2025, the law would require clear window film or security glazing that meets a nationally recognized test standard for forced entry resistance, such as the ASTM F3561 standard, for all exterior entries, doors with adjoining glazing, and secure interior vestibules used as primary entrances.",
      "rationale": "Within the established public-school scope, conveys the effective construction date, permitted protective materials, required testing standard, and covered entrance and vestibule glazing."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The state-level safety team would be responsible for developing and updating compliance guidelines",
      "rationale": "Identifies the responsible team and its duties to develop and update compliance guidelines."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The state-level safety team would be responsible for developing and updating compliance guidelines and sending them to the state fire marshal to be included in rules.",
      "rationale": "Conveys the team's duty to transmit its guidelines to the state fire marshal for incorporation into rules."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The state fire marshal is authorized to create these rules according to the Uniform Administrative Procedures Act.",
      "rationale": "Conveys both the fire marshal's rulemaking authority and the required administrative procedure."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The provisions for establishing guidelines and rules would take effect when the act becomes law, while all other provisions would take effect July 1, 2025.",
      "rationale": "Accurately distinguishes the immediate effective date for guidelines and rulemaking from the July 1, 2025, effective date for all other purposes."
    }
  ]
}
